import { csvFor, nextCode, summarize, validateRequest } from './domain.mjs';

const seedRequests = [
  {id:'1',code:'SOL-0027',title:'Fuga de agua en laboratorio',category:'Mantenimiento',priority:'Urgente',status:'En progreso',assignee:'Mario Céspedes',location:'Laboratorio de Química',date:'2026-09-28',description:'Se observa una fuga continua debajo del lavamanos principal.',hours:3},
  {id:'2',code:'SOL-0026',title:'Proyector sin señal',category:'Equipamiento',priority:'Alta',status:'Pendiente',assignee:'Sin asignar',location:'Edificio B · Aula 12',date:'2026-09-28',description:'El proyector enciende pero no reconoce ninguna entrada HDMI.',hours:1},
  {id:'3',code:'SOL-0025',title:'Acceso a plataforma académica',category:'Soporte tecnológico',priority:'Media',status:'Resuelta',assignee:'Diego Flores',location:'Facultad de Ingeniería',date:'2026-09-27',description:'La cuenta del estudiante mostraba un error al iniciar sesión.',hours:4},
  {id:'4',code:'SOL-0024',title:'Luminaria del pasillo dañada',category:'Infraestructura',priority:'Media',status:'Pendiente',assignee:'Lucía Rojas',location:'Bloque C · Piso 2',date:'2026-09-27',description:'Tres luminarias del pasillo no encienden durante la noche.',hours:8},
  {id:'5',code:'SOL-0023',title:'Revisión de aire acondicionado',category:'Mantenimiento',priority:'Baja',status:'Cerrada',assignee:'Mario Céspedes',location:'Biblioteca · Sala 3',date:'2026-09-26',description:'El equipo emitía ruido constante y fue revisado.',hours:12},
  {id:'6',code:'SOL-0022',title:'Teclado del kiosco no responde',category:'Equipamiento',priority:'Alta',status:'En progreso',assignee:'Sofía Vargas',location:'Hall principal',date:'2026-09-25',description:'Varias teclas del kiosco de autoservicio dejaron de responder.',hours:6},
];
const resources = [
  {name:'Proyectores multimedia',place:'Aulas y auditorios',available:18,total:24,status:'Operativo',symbol:'▰'},
  {name:'Equipos de cómputo',place:'Laboratorios',available:46,total:52,status:'Operativo',symbol:'▣'},
  {name:'Aires acondicionados',place:'Bloques A–C',available:29,total:34,status:'En revisión',symbol:'❄'},
  {name:'Kioscos de autoservicio',place:'Accesos principales',available:5,total:7,status:'En revisión',symbol:'◫'},
  {name:'Salas de reuniones',place:'Edificio administrativo',available:8,total:8,status:'Disponible',symbol:'▦'},
  {name:'Puntos de red',place:'Todo el campus',available:112,total:120,status:'Operativo',symbol:'⌁'},
];
let requests = JSON.parse(localStorage.getItem('campus-connect-requests') || 'null') || seedRequests;
const $ = (s) => document.querySelector(s); const $$ = (s) => [...document.querySelectorAll(s)];
const persist = () => localStorage.setItem('campus-connect-requests', JSON.stringify(requests));
const esc = (v='') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const toast = (message) => { const node=$('#toast'); node.textContent=message; node.classList.add('show'); setTimeout(()=>node.classList.remove('show'),2200); };
const badge = (text, attr='state') => `<span class="badge" data-${attr}="${esc(text)}">${esc(text)}</span>`;

function go(view){ $$('.view').forEach(x=>x.classList.toggle('active',x.id===`${view}View`)); $$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view)); const titles={dashboard:'Resumen general',requests:'Gestión de solicitudes',resources:'Recursos institucionales',reports:'Reportes'}; $('#pageTitle').textContent=titles[view]; $('.sidebar').classList.remove('open'); render(); }

function metricsHtml(data){return `<article class="metric"><span>Solicitudes totales</span><strong>${data.total}</strong><small>Histórico registrado</small></article><article class="metric"><span>Pendientes</span><strong>${data.pending}</strong><small>Requieren asignación</small></article><article class="metric"><span>En progreso</span><strong>${data.active}</strong><small>Atención activa</small></article><article class="metric"><span>Tiempo promedio</span><strong>${data.avgHours} h</strong><small>Hasta la resolución</small></article>`}
function barChart(items){ const max=Math.max(1,...items.map(x=>x.value)); return items.map(x=>`<div><div class="bar-label"><span>${esc(x.label)}</span><strong>${x.value}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${x.value/max*100}%"></div></div></div>`).join(''); }

function renderDashboard(){ const s=summarize(requests); $('#metrics').innerHTML=metricsHtml(s); $('#pendingBadge').textContent=s.pending; $('#attentionCount').textContent=s.pending+s.active; $('#recentList').innerHTML=requests.slice(0,4).map(r=>`<div class="request-row"><div class="request-icon">${esc(r.code.slice(-2))}</div><div><strong>${esc(r.title)}</strong><small>${esc(r.code)} · ${esc(r.location)}</small></div>${badge(r.status)}</div>`).join(''); const cats=['Mantenimiento','Soporte tecnológico','Infraestructura','Equipamiento','Otros servicios'].map(label=>({label,value:requests.filter(r=>r.category===label).length})); $('#categoryChart').innerHTML=barChart(cats); }
function filteredRequests(){ const q=$('#searchInput')?.value.toLowerCase()||''; const st=$('#statusFilter')?.value||''; return requests.filter(r=>(!st||r.status===st)&&[r.code,r.title,r.location].some(v=>v.toLowerCase().includes(q))); }
function renderRequests(){ const list=filteredRequests(); $('#requestsTable').innerHTML=list.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>${esc(r.code)} · ${esc(r.location)}</small></td><td>${esc(r.category)}</td><td>${badge(r.priority,'priority')}</td><td>${badge(r.status)}</td><td>${esc(r.assignee)}</td><td>${new Date(`${r.date}T12:00:00`).toLocaleDateString('es-BO',{day:'2-digit',month:'short'})}</td><td><div class="row-actions"><button data-edit="${r.id}" title="Editar">✎</button><button data-delete="${r.id}" title="Eliminar">×</button></div></td></tr>`).join(''); $('#emptyRequests').hidden=!!list.length; }
function renderResources(){ $('#resourceGrid').innerHTML=resources.map(r=>`<article class="resource-card"><div class="resource-card-top"><div class="resource-symbol">${r.symbol}</div>${badge(r.status)}</div><h3>${r.name}</h3><p>${r.place}</p><div class="resource-meta"><span>Disponibles</span><strong>${r.available} / ${r.total}</strong></div></article>`).join(''); }
function renderReports(){ const s=summarize(requests); $('#reportMetrics').innerHTML=metricsHtml(s); const states=['Pendiente','En progreso','Resuelta','Cerrada']; const colors=['#f6c453','#4b88c5','#4b9b69','#8a9692']; const counts=states.map(x=>requests.filter(r=>r.status===x).length); let acc=0; const stops=counts.map((n,i)=>{const start=acc;acc+=requests.length?n/requests.length*360:0;return `${colors[i]} ${start}deg ${acc}deg`}).join(','); $('#statusDonut').innerHTML=`<div class="donut" style="background:conic-gradient(${stops})"><strong>${requests.length}</strong></div><div class="legend">${states.map((x,i)=>`<span style="--color:${colors[i]}">${x}: <strong>${counts[i]}</strong></span>`).join('')}</div>`; $('#priorityChart').innerHTML=barChart(['Urgente','Alta','Media','Baja'].map(label=>({label,value:requests.filter(r=>r.priority===label).length}))); }
function render(){renderDashboard();renderRequests();renderResources();renderReports();}

function openDialog(item=null){ $('#requestForm').reset(); $('#requestId').value=item?.id||''; $('#dialogTitle').textContent=item?'Editar solicitud':'Nueva solicitud'; if(item) ['title','category','priority','location','status','assignee','description'].forEach(k=>$(`#${k}`).value=item[k]); $$('.error').forEach(x=>x.textContent=''); $('#requestDialog').showModal(); }
function saveRequest(event){ event.preventDefault(); const item={title:$('#title').value,category:$('#category').value,priority:$('#priority').value,location:$('#location').value,status:$('#status').value,assignee:$('#assignee').value,description:$('#description').value}; const errors=validateRequest(item); $$('.error').forEach(x=>x.textContent=errors[x.dataset.error]||''); if(Object.keys(errors).length)return; const id=$('#requestId').value; if(id){const old=requests.find(x=>x.id===id);Object.assign(old,item);toast('Solicitud actualizada');}else{requests.unshift({...item,id:crypto.randomUUID(),code:nextCode(requests),date:new Date().toISOString().slice(0,10),hours:0});toast('Solicitud registrada');} persist();$('#requestDialog').close();render();}
function deleteRequest(id){ const item=requests.find(x=>x.id===id); if(!item||!confirm(`¿Eliminar ${item.code}? Esta acción no se puede deshacer.`))return; requests=requests.filter(x=>x.id!==id);persist();render();toast('Solicitud eliminada'); }
function exportCsv(){ const blob=new Blob(['\ufeff'+csvFor(requests)],{type:'text/csv;charset=utf-8'}); const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`campus-connect-solicitudes-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);toast('Reporte exportado'); }

$$('.nav-item').forEach(x=>x.addEventListener('click',()=>go(x.dataset.view))); $$('[data-go]').forEach(x=>x.addEventListener('click',()=>go(x.dataset.go))); $('#menuBtn').addEventListener('click',()=>$('.sidebar').classList.toggle('open')); $('#newRequestBtn').addEventListener('click',()=>openDialog()); $('#requestForm').addEventListener('submit',saveRequest); $('#searchInput').addEventListener('input',renderRequests); $('#statusFilter').addEventListener('change',renderRequests); $('#requestsTable').addEventListener('click',e=>{const edit=e.target.dataset.edit,del=e.target.dataset.delete;if(edit)openDialog(requests.find(x=>x.id===edit));if(del)deleteRequest(del)}); $('#exportBtn').addEventListener('click',exportCsv); $('#addResourceBtn').addEventListener('click',()=>toast('Módulo listo para conectarse al inventario institucional')); render();
